/**
 * What makes the editor a full-page app (shared by the React and Vue apps): the document or room
 * in the address, the example documents, stored settings and autosave, the window title, opening
 * files dropped on the window or passed by the installed app, and the page API on `window`.
 */
import { DISCARD_PROMPT, DOCX_MIME, type Example, installPageApi, type Marginline, type MarginlineOptions } from '@marginline/core';

const APP = 'Marginline';

/** Example documents shipped with the app (generated by scripts/make-fixtures.mjs). */
export const EXAMPLES: Example[] = [
  { id: 'agreement', label: 'Review', url: './examples/agreement.docx', description: 'Comments and tracked changes' },
  { id: 'template', label: 'Templating', url: './examples/template.docx', description: 'Fillable fields' },
  { id: 'long', label: '300 pages', url: './examples/long-report.docx', description: 'A long document' },
  { id: 'tables', label: 'Tables & columns', url: './examples/tables-columns.docx', description: 'Tables, a picture and two columns' },
  { id: 'international', label: 'International & RTL', url: './examples/international.docx', description: 'Right-to-left and CJK text' },
  { id: 'formatting', label: 'Formatting', url: './examples/formatting.docx', description: 'Lists, styles, notes and headers' },
];

/** Options from the address: `?room=` joins a shared document, `?src=` and `?example=` open one, `?new` skips recovery. */
export function shellOptions(): MarginlineOptions {
  const params = new URLSearchParams(location.search);
  const src = params.get('src');
  const example = EXAMPLES.find((x) => x.id === params.get('example'));
  return {
    examples: EXAMPLES,
    storageKey: 'marginline',
    autosave: 'marginline',
    offerRecovery: !params.has('new'),
    globalShortcuts: true,
    room: params.get('room') ?? undefined,
    document: src ? { url: src, name: decodeURIComponent(src.split('/').pop() || 'Document.docx') } : example ? { url: example.url } : undefined,
  };
}

interface LaunchQueue {
  setConsumer(fn: (p: { files: FileSystemFileHandle[] }) => void): void;
}

/** Connect the ready editor to the page; returns the function that disconnects it. */
export function connectShell(ml: Marginline, options: MarginlineOptions): () => void {
  const editor = ml.activeEditor.native;
  const title = (dirty: boolean) => {
    document.title = `${dirty ? '• ' : ''}${editor.fileName.replace(/\.docx$/i, '')} – ${APP}`;
  };
  if (options.document || options.room) title(editor.dirty);
  const offs = [
    editor.on('change', ({ dirty }) => title(dirty)),
    editor.on('rename', () => title(editor.dirty)),
    editor.on('load', () => title(false)),
    installPageApi(ml),
  ];

  // Open .docx files dropped anywhere on the window.
  const isDocx = (f: File) => /\.(docx|dotx)$/i.test(f.name) || f.type === DOCX_MIME;
  const over = (e: DragEvent) => {
    if (Array.from(e.dataTransfer?.items ?? []).some((i) => i.kind === 'file')) e.preventDefault();
  };
  const drop = (e: DragEvent) => {
    const file = Array.from(e.dataTransfer?.files ?? []).find(isDocx);
    if (!file) return;
    e.preventDefault();
    e.stopPropagation();
    if (ml.dirty && !window.confirm(DISCARD_PROMPT)) return;
    void ml.ui.open(file);
  };
  const before = (e: BeforeUnloadEvent) => {
    if (ml.dirty) {
      e.preventDefault();
      e.returnValue = '';
    }
  };
  const keys = (e: KeyboardEvent) => {
    if ((e.ctrlKey || e.metaKey) && !e.shiftKey && e.key.toLowerCase() === 'o') {
      e.preventDefault();
      void ml.ui.open();
    }
  };
  window.addEventListener('dragover', over);
  window.addEventListener('drop', drop, true);
  window.addEventListener('beforeunload', before);
  window.addEventListener('keydown', keys);

  // Files opened through the installed app (PWA file handling).
  (window as unknown as { launchQueue?: LaunchQueue }).launchQueue?.setConsumer(async (p) => {
    const handle = p.files?.[0];
    if (handle) void ml.ui.open(await handle.getFile());
  });

  return () => {
    for (const off of offs) off();
    window.removeEventListener('dragover', over);
    window.removeEventListener('drop', drop, true);
    window.removeEventListener('beforeunload', before);
    window.removeEventListener('keydown', keys);
  };
}

/** The installed app works offline (production builds only). */
export function registerServiceWorker() {
  if ('serviceWorker' in navigator) {
    window.addEventListener('load', () => {
      navigator.serviceWorker.register('./sw.js').catch(() => undefined);
    });
  }
}
